/** The buttons every install starts with. A user's config file adds to, edits or hides these. */
export type DefaultReply = {
  id: string
  label: string
  text: string
  send?: boolean
  more?: boolean
  style?: 'solid' | 'outline'
  /** `asking` shows the button only while Claude's last message asks a question. Default `always`. */
  when?: 'always' | 'asking'
  /** A glyph drawn before the label. Left out, the color's role picks one. */
